actions.script:
const result = ec.service.sync().name('org.moqui.report.ReportServices.query#Documents').parameters({datasetId:'otel_errors',
    queryString:'fingerprint:'+JSON.stringify(String(fingerprint)),from:from || 'now-7d',thru:thru || 'now',pageSize:1}).call()
errorGroup = result.hits && result.hits.length ? result.hits[0].body : {}
sampleTraces = errorGroup.sample_trace_ids || []
